def semver_sort(versions):
    def parse_version(v):
        # Split by '+' to remove build metadata
        v_without_build = v.split('+')[0]

        # Split by '-' to separate version from pre-release
        if '-' in v_without_build:
            version_part, prerelease_part = v_without_build.split('-', 1)
        else:
            version_part = v_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = version_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease_part:
            identifiers = prerelease_part.split('.')
            prerelease_identifiers = []
            for ident in identifiers:
                # Check if identifier is all digits
                if ident.isdigit():
                    prerelease_identifiers.append((0, int(ident)))
                else:
                    prerelease_identifiers.append((1, ident))
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def sort_key(v):
        parsed = parse_version(v)
        major, minor, patch, prerelease_identifiers = parsed

        # For sorting: version without pre-release comes after version with pre-release
        # We use a tuple where None (no pre-release) sorts after a list (has pre-release)
        # So we need to invert: use (False, ...) for with pre-release and (True, ...) for without
        if prerelease_identifiers is None:
            prerelease_key = (True,)  # No pre-release sorts after
        else:
            prerelease_key = (False, prerelease_identifiers)  # Has pre-release sorts before

        return (major, minor, patch, prerelease_key)

    # Sort using stable sort to maintain input order for equal precedence
    return sorted(versions, key=sort_key)

